with metrics as (select *, last_value(cost) ignore nulls over (partition by status, order_id order by delivered_date, id rows between unbounded preceding and current row) as last_known_cost, sum(cost) over (partition by status order by shipped_date, id rows between unbounded preceding and current row) as running_cost from shipments) select s.id, s.order_id, s.delivered_date, s.status, s.running_cost, (select avg(p2.amount) from payments p2 where p2.order_id = s.order_id) as avg_payment_amount from metrics s order by avg_payment_amount desc
